import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Recent opponent behavior (last 6 rounds)
    w = 6 if n >= 6 else n
    recent = history[-w:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')

    # Consecutive defections at the tail of opponent
    streak = 0
    for a, b in reversed(history):
        if b == 'D':
            streak += 1
        else:
            break

    # Consecutive defections at the tail of self
    my_streak = 0
    for a, b in reversed(history):
        if a == 'D':
            my_streak += 1
        else:
            break

    # Total counts
    opp_d = sum(1 for a, b in history if b == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for a, b in history if a == 'D')

    last_me, last_opp = history[-1]

    # Opening: cooperate early to encourage mutual cooperation.
    if n < 6:
        if last_opp == 'D' and n >= 2:
            return 'D'
        return 'C'

    # Very strong ongoing defection by opponent: defend (but avoid endless DD)
    if opp_d >= n - 1 and n >= 8:
        # Opponent essentially never cooperates; defect, with rare probe.
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Opponent just defected:
    if last_opp == 'D':
        # Long defection streak: punish, but attempt occasional reset
        if streak >= 3:
            if my_streak >= 3 and rng.random() < 0.18:
                return 'C'
            return 'D'
        # Short streak: retaliate, but with small chance to forgive quickly
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # Overwhelmingly cooperative opponent.
    if n >= 10 and opp_c >= int(0.9 * n):
        # Exploit cautiously but preserve CC.  Keep cooperation most of the time.
        # Near end, exploit a bit more.
        remaining = 100 - n
        if remaining <= 3 and opp_d <= 1:
            return 'D'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Strongly cooperative recent behavior.
    if recent_opp_d == 0 and n >= 8:
        # Consider probe only if opponent has never defected and we've been nice.
        if opp_d == 0 and n >= 20 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Mixed opponent: use short-window reciprocity with forgiveness.
    if recent_opp_d <= 1:
        return 'C'

    # Moderate defection in recent window: mostly defend.
    if recent_opp_d >= 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Default: cooperate, occasional probe if we've been very cooperative.
    if my_d == 0 and n >= 15 and rng.random() < 0.05:
        return 'D'
    return 'C'
